-- UEFA 2026/27: 36-team Swiss league phases for each competition. Seeded clubs are the published league-phase participants.
BEGIN;
CREATE TABLE IF NOT EXISTS uefa_competitions (id TEXT PRIMARY KEY, season_id TEXT NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'league_phase', league_phase_clubs SMALLINT NOT NULL DEFAULT 36, matches_per_club SMALLINT NOT NULL DEFAULT 8, UNIQUE(season_id,code));
CREATE TABLE IF NOT EXISTS uefa_clubs (id TEXT PRIMARY KEY, name TEXT NOT NULL, country_code TEXT NOT NULL, reputation SMALLINT NOT NULL DEFAULT 60, team_strength SMALLINT NOT NULL DEFAULT 60, domestic_division_id TEXT, source_url TEXT, source_checked_at DATE DEFAULT DATE '2026-10-21');
CREATE TABLE IF NOT EXISTS uefa_participants (id TEXT PRIMARY KEY, competition_id TEXT NOT NULL REFERENCES uefa_competitions(id), club_id TEXT NOT NULL REFERENCES uefa_clubs(id), entry_stage TEXT NOT NULL DEFAULT 'league_phase', group_position SMALLINT, points SMALLINT NOT NULL DEFAULT 0, played SMALLINT NOT NULL DEFAULT 0, wins SMALLINT NOT NULL DEFAULT 0, draws SMALLINT NOT NULL DEFAULT 0, losses SMALLINT NOT NULL DEFAULT 0, goals_for SMALLINT NOT NULL DEFAULT 0, goals_against SMALLINT NOT NULL DEFAULT 0, UNIQUE(competition_id,club_id));
CREATE TABLE IF NOT EXISTS uefa_fixtures (id TEXT PRIMARY KEY, competition_id TEXT NOT NULL REFERENCES uefa_competitions(id), season_id TEXT NOT NULL, matchday SMALLINT NOT NULL, kickoff_date DATE NOT NULL, home_club_id TEXT NOT NULL REFERENCES uefa_clubs(id), away_club_id TEXT NOT NULL REFERENCES uefa_clubs(id), stage TEXT NOT NULL DEFAULT 'league_phase', home_goals SMALLINT, away_goals SMALLINT, status TEXT NOT NULL DEFAULT 'scheduled', UNIQUE(competition_id,matchday,home_club_id,away_club_id));
CREATE INDEX IF NOT EXISTS idx_uefa_fixtures_date ON uefa_fixtures(season_id,kickoff_date,competition_id);
INSERT INTO uefa_competitions(id,season_id,code,name,format,league_phase_clubs,matches_per_club) VALUES ('uefa-ucl-2026-2027','2026-2027','UCL','UEFA Champions League','swiss_league',36,8),('uefa-uel-2026-2027','2026-2027','UEL','UEFA Europa League','swiss_league',36,8),('uefa-uecl-2026-2027','2026-2027','UECL','UEFA Conference League','swiss_league',36,6) ON CONFLICT(id) DO UPDATE SET name=EXCLUDED.name,format=EXCLUDED.format,league_phase_clubs=EXCLUDED.league_phase_clubs,matches_per_club=EXCLUDED.matches_per_club;
